import{_ as t,o as n,c as o,a5 as a}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Plan — G5 Task Management (Mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g5-task-management/plan.md","filePath":"mobile/features/g5-task-management/plan.md"}'),c={name:"mobile/features/g5-task-management/plan.md"};function i(l,e,h,s,r,d){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="plan-—-g5-task-management-mobile" tabindex="-1">Plan — G5 Task Management (Mobile) <a class="header-anchor" href="#plan-—-g5-task-management-mobile" aria-label="Permalink to &quot;Plan — G5 Task Management (Mobile)&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — chi tiết API/flows/business rules đầy đủ. File này là bản tóm tắt thứ tự implement + quyết định kỹ thuật chốt.</p><h2 id="thu-tu-implement-theo-dependency" tabindex="-1">Thứ tự implement (theo dependency) <a class="header-anchor" href="#thu-tu-implement-theo-dependency" aria-label="Permalink to &quot;Thứ tự implement (theo dependency)&quot;">​</a></h2><ol><li><strong>Task List</strong> (FR 3.6.4) — list + filter + pull-to-refresh/infinite scroll. Nền tảng cho Detail/Kanban.</li><li><strong>Task Detail</strong> — gọi cả <code>workflow</code> (metadata) và <code>review</code> (action-gating), <code>allowedActions</code> là nguồn chân lý cho show/hide nút, không tự suy luận rule ở client.</li><li><strong>Status transitions</strong> (start/submit/withdraw/approve/reject) — optimistic update + xử lý 409 conflict.</li><li><strong>Kanban Board</strong> (V1, 1 kiểu) — dùng cùng cache key với Task Detail để tránh lệch state.</li><li><strong>Comment Thread</strong> (FR 3.6.3) — tái dùng picker camera/gallery đã làm ở G2.</li><li><strong>Realtime polling</strong> — thêm cuối cùng, không chặn các phần khác.</li></ol><h2 id="quyet-đinh-ky-thuat-đa-chot" tabindex="-1">Quyết định kỹ thuật đã chốt <a class="header-anchor" href="#quyet-đinh-ky-thuat-đa-chot" aria-label="Permalink to &quot;Quyết định kỹ thuật đã chốt&quot;">​</a></h2><ul><li><strong>Nguồn dữ liệu đúng: <code>TaskDocument</code> (MongoDB) qua <code>TaskListItemResponse</code>/<code>TaskWorkflowResponse</code>/<code>TaskReviewResponse</code></strong> — KHÔNG dùng <code>TaskResponse</code> (map từ SQL <code>Task.java</code> tối giản, không có status/assignee/comment).</li><li><strong>Client thấy TOÀN BỘ Task trong Workspace</strong> (Q13, CONFIRMED) — không tự thêm filter ẩn theo role, kể cả Client. &quot;Chỉ Task của tôi&quot; là filter UI tùy chọn, không phải default ẩn.</li><li><strong>Mọi optimistic-concurrency field</strong> (<code>expectedRevision</code>/<code>expectedApprovalRound</code>/<code>expectedPostContentVersion</code>) phải gửi đúng giá trị đọc được từ response gần nhất — server reject nếu stale.</li><li><strong>Reject bắt buộc có <code>comment</code> ở UI</strong> dù DTO backend không <code>@NotBlank</code> — validate client-side theo yêu cầu BA.</li><li><strong>Realtime: polling nhẹ (15-30s), KHÔNG dùng WebSocket</strong> — <code>TaskContentWebSocketController</code> chỉ phục vụ Yjs content editor (ngoài scope G5), không phát event status/comment. Quyết định này <strong>chưa chính thức xác nhận với team</strong>, chỉ là khuyến nghị của spec — cần confirm trước khi code nếu muốn đổi sang WS ngay từ đầu.</li><li><strong>Content Editor (FR 3.6.10) và Gantt View (FR 3.6.6) KHÔNG làm trên mobile</strong> — Content Editor vì Yjs CRDT realtime quá phức tạp cho effort capstone; Gantt vì màn hình mật độ cao không phù hợp điện thoại. Cả 2 là judgment call của spec, <strong>cần user/stakeholder duyệt lại</strong> trước khi chốt vào implementation plan thật.</li></ul><h2 id="viec-can-xac-nhan-truoc-khi-code-chua-lam-xem-spec-muc-8" tabindex="-1">Việc cần xác nhận trước khi code (chưa làm, xem spec mục 8) <a class="header-anchor" href="#viec-can-xac-nhan-truoc-khi-code-chua-lam-xem-spec-muc-8" aria-label="Permalink to &quot;Việc cần xác nhận trước khi code (chưa làm, xem spec mục 8)&quot;">​</a></h2><ul><li>Realtime polling vs WS topic riêng — xác nhận trước khi code, đổi sau tốn công refactor cache layer.</li><li>Preview nội dung Post (type=POST) trong Task Detail — quyết định có làm không, đọc <code>TaskPostResponse</code> nếu làm.</li><li>Conflict UX 409 — thiết kế rõ thông báo lỗi, tình huống dễ gặp trên mobile (nhiều người xem/sửa cùng lúc, mạng chậm hơn web).</li></ul><h2 id="rui-ro-con-mo" tabindex="-1">Rủi ro còn mở <a class="header-anchor" href="#rui-ro-con-mo" aria-label="Permalink to &quot;Rủi ro còn mở&quot;">​</a></h2><ul><li>Gantt loại bỏ hoàn toàn khỏi roadmap mobile là đề xuất riêng của spec, chưa phải quyết định chính thức từ BA/stakeholder.</li><li>5 loại TaskType (POST/LIVESTREAM/SURVEY/EVENT_PLAN/PRESS_RECOMMENDATION) chỉ POST có content workflow tích hợp — các type khác chỉ hiện metadata khung sườn trên mobile, khớp với việc các module đó chưa có API/UI riêng ngay cả trên web.</li></ul>',10)])])}const u=t(c,[["render",i]]);export{g as __pageData,u as default};
